import { htmlPreviewDescription, htmlRenderDescription } from "./html.ts";

/** Metadata only: schemas and handlers remain with their owning toolkit. */
export type AgentSurfaceEffect = "read" | "write" | "destructive";
export interface AgentSurfaceExample {
  readonly title: string;
  readonly args: Readonly<Record<string, unknown>>;
  readonly expect: Readonly<Record<string, unknown>>;
}
export interface AgentSurfaceEntry {
  readonly resource: string;
  readonly verb: string;
  readonly name: string;
  readonly toolkit: string;
  readonly summary: string;
  readonly description: string;
  readonly effect: AgentSurfaceEffect;
  readonly hostRoutable: boolean;
  readonly requires: "thread" | "client" | "either";
  readonly dryRun: "supported" | "unsupported";
  readonly humanSteps: ReadonlyArray<
    "secret" | "approval" | "question" | "sign_in" | "host_trust" | "pairing"
  >;
  readonly annotations: {
    readonly title?: string;
    readonly idempotentHint: boolean;
    readonly openWorldHint: boolean;
  };
}

const entry = <const E extends AgentSurfaceEntry>(value: E) => ({
  ...value,
  path: `${value.resource}.${value.verb}` as `${E["resource"]}.${E["verb"]}`,
  legacyNames: [value.name],
  // Input resolves through Tool.getJsonSchema (including dynamic tools); outputs
  // reference the named tool's schema slots. No server imports enter contracts.
  schemaRefs: {
    toolkit: value.toolkit as E["toolkit"],
    tool: value.name as E["name"],
    input: "input",
    output: "successSchema",
    failure: "failureSchema",
  } as const,
  examples: [] as ReadonlyArray<AgentSurfaceExample>,
});

